<?php

declare(strict_types=1);

namespace App\Message;

/**
 * Carries one build request onto the `q.builds` queue, where publish-worker consumes it.
 * StaticSiteController dispatches it and config/packages/messenger.yaml routes it to the `builds` transport.
 * Property names are snake_case because Messenger's symfony_serializer uses them verbatim as JSON keys, and publish-worker's BuildJob decodes by the same names.
 * The class has no getters because ObjectNormalizer would turn each getter into an extra JSON key.
 *
 * @param ?string $build_id Per-build UUID v7 generated by the client, for tracing a job across services; names the job's folder under BUILDS_DIR.
 *                         null for a delete, which builds nothing.
 * @param string $static_site_id Identifies the site across builds, as a lower-case UUID v7.
 * @param BuildOperation $operation What publish-worker does with the site.
 * @param string $slug Names the published site directory under PAGES_DIR which translates to the uri path of the published site.
 *                     It is restricted to [A-Za-z0-9_-]{1,128} and StaticSiteController rejects anything else with a 400.
 *                     It is unique across sites: StaticSiteController answers 409 for a slug another site holds.
 * @param string $callback_status_url Callback url to update the build status.
 * @param string $created_at Timestamp when the job was created by the publish API.
 * @param ?string $title Site title, shown in the page header; set for create and update.
 *                       Separate from $slug because the slug allow-list excludes spaces.
 * @param ?string $content_download_url Download url for the build assets; set for create and update.
 * @param mixed $render_options Any JSON value from the request, passed unchecked to ssg-library, which validates it.
 *                              null when absent.
 */
final class BuildJob
{
    public function __construct(
        public readonly ?string $build_id,
        public readonly string $static_site_id,
        public readonly BuildOperation $operation,
        public readonly string $slug,
        public readonly string $callback_status_url,
        public readonly string $created_at,
        public readonly ?string $title = null,
        public readonly ?string $content_download_url = null,
        public readonly mixed $render_options = null,
    ) {
    }
}
